PROGRAM='"""One synthetic key; no blind retries, bare deletes or production invocation here."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nimport re\nimport signal\nimport socket\nimport stat\nfrom pathlib import Path\nfrom uuid import uuid4\n\nimport boto3\nfrom botocore.config import Config\nfrom botocore.exceptions import ClientError\n\nENDPOINT = "http://platform-minio:9000"\nBUCKET = "orbbec-agent-attachments"\nFENCE = {"platform-erasure-fence": "v1"}\n\n\ndef sha(value):\n    return hashlib.sha256(value).hexdigest()\n\n\nclass Rejected(Exception):\n    pass\n\n\nclass Deadline(BaseException):\n    pass\n\n\ndef require(value, code):\n    if not value:\n        raise Rejected(code)\n\n\nclass Probe:\n    def __init__(self, client, path, binding):\n        self.client, self.path, self.binding = client, path, binding\n        self.key = (\n            "platform-synthetic-conditional-probe/"\n            + binding["run_id"]\n            + "/"\n            + uuid4().hex\n        )\n        self.owned = []\n        self.events = []\n        self.rejections = []\n        self.state = "started"\n        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)\n        os.close(fd)\n        self.record("reserved")\n\n    def record(self, stage, **values):\n        self.events.append({"stage": stage, **values})\n        payload = {\n            "binding": self.binding,\n            "key": self.key,\n            "bucket": BUCKET,\n            "owned_versions": self.owned,\n            "events": self.events,\n            "status": self.state,\n        }\n        temporary = self.path.with_name(self.path.name + ".part")\n        fd = os.open(temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)\n        with os.fdopen(fd, "w") as output:\n            json.dump(payload, output, sort_keys=True)\n            output.flush()\n            os.fsync(output.fileno())\n        os.replace(temporary, self.path)\n        fd = os.open(self.path.parent, os.O_RDONLY)\n        try:\n            os.fsync(fd)\n        finally:\n            os.close(fd)\n\n    def versions(self):\n        marker = {}\n        rows = []\n        seen = set()\n        for _ in range(8):\n            value = self.client.list_object_versions(\n                Bucket=BUCKET, Prefix=self.key, MaxKeys=1000, **marker\n            )\n            require(type(value.get("IsTruncated")) is bool, "listing_incomplete")\n            for kind in ("Versions", "DeleteMarkers"):\n                for row in value.get(kind, []):\n                    if row["Key"] == self.key:\n                        rows.append((kind, row["VersionId"]))\n            require(len(rows) <= 8, "unexpected_versions")\n            if not value["IsTruncated"]:\n                return rows\n            pair = (value.get("NextKeyMarker"), value.get("NextVersionIdMarker"))\n            require(\n                all(isinstance(x, str) and x for x in pair) and pair not in seen,\n                "listing_incomplete",\n            )\n            seen.add(pair)\n            marker = {"KeyMarker": pair[0], "VersionIdMarker": pair[1]}\n        raise Rejected("listing_incomplete")\n\n    def put(self, stage, body, metadata=None, reject=False):\n        self.record(\n            stage + "_sending",\n            request_id=uuid4().hex,\n            body_sha256=sha(body),\n            bytes=len(body),\n            conditional=True,\n        )\n        try:\n            response = self.client.put_object(\n                Bucket=BUCKET,\n                Key=self.key,\n                Body=body,\n                ContentLength=len(body),\n                Metadata=metadata or {},\n                IfNoneMatch="*",\n            )\n        except ClientError as error:\n            status = error.response.get("ResponseMetadata", {}).get("HTTPStatusCode")\n            if reject and status == 412:\n                self.rejections.append(status)\n                self.record(\n                    stage + "_rejected",\n                    http_status=status,\n                    request_id=error.response.get("ResponseMetadata", {}).get(\n                        "RequestId"\n                    ),\n                )\n                return None\n            raise\n        version = response.get("VersionId")\n        if (\n            not isinstance(version, str)\n            or not version\n            or version == "null"\n            or version in self.owned\n        ):\n            raise RuntimeError("unknown version response")\n        self.owned.append(version)\n        self.record(\n            stage + "_received",\n            version=version,\n            request_id=response.get("ResponseMetadata", {}).get("RequestId"),\n        )\n        require(not reject, "conditional_put_not_rejected")\n        return version\n\n    def verify(self, version, body, metadata):\n        require(self.versions() == [("Versions", version)], "version_set_changed")\n        for explicit in (True, False):\n            args = {"Bucket": BUCKET, "Key": self.key}\n            if explicit:\n                args["VersionId"] = version\n            head = self.client.head_object(**args)\n            require(\n                head.get("VersionId") == version\n                and type(head.get("ContentLength")) is int\n                and head["ContentLength"] == len(body)\n                and head.get("Metadata", {}) == metadata,\n                "head_changed",\n            )\n            response = self.client.get_object(**args)\n            stream = response["Body"]\n            try:\n                actual = stream.read(len(body) + 1)\n            finally:\n                stream.close()\n            require(\n                response.get("VersionId") == version and actual == body,\n                "payload_changed",\n            )\n        self.record(\n            "exact_version_and_current_verified", version=version, body_sha256=sha(body)\n        )\n\n    def delete(self, version):\n        require(version in self.owned and version != "null", "delete_not_owned")\n        require(\n            self.client.get_bucket_versioning(Bucket=BUCKET).get("Status") == "Enabled",\n            "versioning_changed",\n        )\n        self.record("delete_sending", version=version, request_id=uuid4().hex)\n        response = self.client.delete_object(\n            Bucket=BUCKET, Key=self.key, VersionId=version\n        )\n        if response.get("VersionId") != version or response.get("DeleteMarker") is True:\n            raise RuntimeError("unknown delete response")\n        require(not self.versions(), "cleanup_incomplete")\n        self.record("delete_verified", version=version)\n\n    def execute(self):\n        failure = None\n        try:\n            require(\n                self.client.get_bucket_versioning(Bucket=BUCKET).get("Status")\n                == "Enabled",\n                "versioning_not_enabled",\n            )\n            require(not self.versions(), "key_not_empty")\n            self.record("key_absent")\n            payload = b"SYNTHETIC conditional PUT production capability probe; no personal data.\\n"\n            version = self.put("payload_put", payload)\n            self.put("conflicting_put", b"SYNTHETIC differing payload.\\n", reject=True)\n            self.verify(version, payload, {})\n            self.delete(version)\n            fence = self.put("fence_put", b"", FENCE)\n            self.put(\n                "after_fence_put", b"SYNTHETIC must not overwrite fence.\\n", reject=True\n            )\n            self.verify(fence, b"", FENCE)\n            self.delete(fence)\n            self.state = "passed"\n        except Rejected as error:\n            self.state, failure = "failed", str(error)\n        except BaseException:  # noqa: BLE001 - retain unknown mutation evidence on signals\n            self.state, failure = "unknown", "request_or_observation_unknown"\n        self.record("finished", failure=failure)\n        return {\n            "status": self.state,\n            "failure": failure,\n            "key_sha256": sha(self.key.encode()),\n            "conditional_rejections": self.rejections,\n            "private_ledger_sha256": sha(self.path.read_bytes()),\n            "cleanup_verified": self.state == "passed",\n            "binding_sha256": sha(json.dumps(self.binding, sort_keys=True).encode()),\n            "boundary": "synthetic S3 only; MinIO generation requires external before/after inspect",\n        }\n\n\ndef private(path, *, directory=False):\n    info = path.lstat()\n    require(\n        path.is_absolute()\n        and not path.is_symlink()\n        and info.st_uid == os.getuid()\n        and stat.S_IMODE(info.st_mode) == (0o700 if directory else 0o600)\n        and (stat.S_ISDIR(info.st_mode) if directory else stat.S_ISREG(info.st_mode)),\n        "private_path_invalid",\n    )\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--binding", type=Path, required=True)\n    parser.add_argument("--evidence", type=Path, required=True)\n    parser.add_argument("--execute", action="store_true")\n    args = parser.parse_args()\n    require(args.execute, "explicit_execution_required")\n    private(args.binding)\n    private(args.evidence, directory=True)\n    binding = json.loads(args.binding.read_bytes())\n    require(\n        set(binding) == {"run_id", "minio", "client", "script_sha256"},\n        "binding_invalid",\n    )\n    require(re.fullmatch("[0-9a-f]{32}", binding["run_id"]), "run_invalid")\n    for name in ("minio", "client"):\n        identity = binding[name]\n        require(\n            re.fullmatch("[0-9a-f]{64}", identity["id"])\n            and re.fullmatch("sha256:[0-9a-f]{64}", identity["image"]),\n            "identity_invalid",\n        )\n    require(\n        type(binding["minio"]["pid"]) is int\n        and binding["minio"]["pid"] > 0\n        and isinstance(binding["minio"]["started_at"], str)\n        and binding["minio"]["started_at"],\n        "generation_invalid",\n    )\n    require(\n        socket.gethostname() == binding["client"]["id"][:12], "client_hostname_mismatch"\n    )\n    require(\n        sha(Path(__file__).read_bytes()) == binding["script_sha256"], "source_changed"\n    )\n    require(signal.getitimer(signal.ITIMER_REAL) == (0.0, 0.0), "existing_timer")\n    secrets = []\n    for name in ("attachment-s3-access-key", "attachment-s3-secret-key"):\n        p = Path("/run/secrets") / name\n        st = p.lstat()\n        require(\n            not p.is_symlink()\n            and stat.S_ISREG(st.st_mode)\n            and stat.S_IMODE(st.st_mode) == 0o600\n            and st.st_uid in (0, 10001),\n            "secret_metadata_invalid",\n        )\n        secrets.append(p.read_text().strip())\n    require(all(secrets), "secret_missing")\n    client = boto3.client(\n        "s3",\n        endpoint_url=ENDPOINT,\n        region_name="us-east-1",\n        aws_access_key_id=secrets[0],\n        aws_secret_access_key=secrets[1],\n        config=Config(\n            signature_version="s3v4",\n            connect_timeout=3,\n            read_timeout=5,\n            retries={"total_max_attempts": 1},\n            proxies={},\n            s3={"addressing_style": "path"},\n        ),\n    )\n\n    def stop(_number, _frame):\n        raise Deadline()\n\n    numbers = (\n        signal.SIGALRM,\n        signal.SIGINT,\n        signal.SIGTERM,\n        signal.SIGHUP,\n        signal.SIGQUIT,\n    )\n    previous = {n: signal.getsignal(n) for n in numbers}\n    try:\n        for n in numbers:\n            signal.signal(n, stop)\n        signal.setitimer(signal.ITIMER_REAL, 90)\n        result = Probe(client, args.evidence / "private-ledger.json", binding).execute()\n    finally:\n        signal.setitimer(signal.ITIMER_REAL, 0)\n        for n, h in previous.items():\n            signal.signal(n, h)\n        client.close()\n    print(json.dumps(result, sort_keys=True))\n    return 0 if result["status"] == "passed" else 1\n\n\nif __name__ == "__main__":\n    try:\n        raise SystemExit(main())\n    except (Exception, Deadline):  # noqa: BLE001 - fixed diagnostics, no private exception output\n        print(\n            \'{"status":"unknown","failure":"probe_failed_private_ledger_requires_inspection"}\'\n        )\n        raise SystemExit(1) from None\n'
import hashlib,json,os,re,signal,stat,subprocess,time
from pathlib import Path
os.umask(0o077)
RUN='4cc5854e73974db494203f70a702ee9a'
IMAGE='sha256:cbe282151ff678b9e0573102267b71ba1c32888603b4d818fa07be22ccc50442'
MINIO='de10f2bd60988f07a77c685b55919cfb98ebed8e6792d41aa7c5e2a9a0b34238'
MINIO_IMAGE='sha256:d249d1fb6966de4d8ad26c04754b545205ff15a62e4fd19ebd0f26fa5baacbc0'
NAME='hr-conditional-probe-'+RUN
ROOT=Path('/opt/orbbec-agent-platform/private')/NAME
DOCKER=['/usr/bin/docker','--host','unix:///var/run/docker.sock']
def command(args,timeout=15):
 r=subprocess.run(DOCKER+args,capture_output=True,timeout=timeout,env={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8'})
 if args[:2]==['start','--attach']:
  write(ROOT/'client-stdout.json',r.stdout);write(ROOT/'client-stderr.log',r.stderr)
 if r.returncode:raise RuntimeError('docker_command_failed')
 return r.stdout
def inspect(identity):return json.loads(command(['inspect',identity]))[0]
def minio():
 r=inspect(MINIO)
 if r['Image']!=MINIO_IMAGE or not r['State']['Running'] or r['Name']!='/orbbec-agent-platform-platform-minio-1':raise RuntimeError('minio_identity_changed')
 return {'id':r['Id'],'image':r['Image'],'pid':r['State']['Pid'],'started_at':r['State']['StartedAt']}
def write(path,body):
 fd=os.open(path,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
 with os.fdopen(fd,'wb') as f:
  os.fchown(f.fileno(),10001,10001);f.write(body);f.flush();os.fsync(f.fileno())
def interrupt(number,frame):raise RuntimeError('interrupted')
for sig in (signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGQUIT):signal.signal(sig,interrupt)
container=None;attempted=False
receipt={'run_id':RUN,'started_at':time.time(),'status':'running','services_changed':False,'database_changed':False,'synthetic_s3_mutations':True}
try:
 if os.getuid()!=0 or ROOT.parent.is_symlink() or stat.S_IMODE(ROOT.parent.stat().st_mode)!=0o700:raise RuntimeError('private_parent_invalid')
 ROOT.mkdir(mode=0o700,exist_ok=False);os.chown(ROOT,10001,10001)
 (ROOT/'evidence').mkdir(mode=0o700);os.chown(ROOT/'evidence',10001,10001)
 write(ROOT/'probe.py',PROGRAM.encode())
 before=minio();receipt['minio_before']=before
 attempted=True
 container=command(['create','--name',NAME,'--label','hr.probe.run='+RUN,'--read-only','--restart','no','--network','orbbec-agent-platform-internal','--cap-drop','ALL','--security-opt','no-new-privileges:true','--user','10001:10001','--mount','type=bind,src='+str(ROOT)+',dst=/probe,readonly','--mount','type=bind,src='+str(ROOT/'evidence')+',dst=/evidence','--mount','type=volume,src=orbbec-agent-platform-api-secrets,dst=/run/secrets,readonly','--entrypoint','python',IMAGE,'/probe/probe.py','--binding','/evidence/binding.json','--evidence','/evidence','--execute']).decode().strip()
 if not re.fullmatch('[0-9a-f]{64}',container):raise RuntimeError('container_id_invalid')
 c=inspect(container)
 if c['Image']!=IMAGE or c['Name']!='/'+NAME or c['Config']['Labels'].get('hr.probe.run')!=RUN:raise RuntimeError('client_identity_invalid')
 binding={'run_id':RUN,'minio':before,'client':{'id':c['Id'],'image':c['Image']},'script_sha256':hashlib.sha256(PROGRAM.encode()).hexdigest()}
 write(ROOT/'evidence/binding.json',json.dumps(binding,sort_keys=True).encode());receipt['binding']=binding
 write(ROOT/'operation.json',json.dumps(receipt).encode())
 result=command(['start','--attach',container],timeout=110)
 receipt['probe']=json.loads(result)
 c=inspect(container)
 if c['State']['Running'] or c['State']['ExitCode']!=0:raise RuntimeError('probe_failed')
 after=minio();receipt['minio_after']=after
 if before!=after:raise RuntimeError('server_generation_changed')
 if receipt['probe'].get('status')!='passed' or receipt['probe'].get('conditional_rejections')!=[412,412] or receipt['probe'].get('cleanup_verified') is not True:raise RuntimeError('probe_not_verified')
 receipt['status']='passed'
except BaseException as error:receipt.update(status='failed',failure_type=type(error).__name__,private_evidence_path=str(ROOT/'evidence'))
finally:
 for sig in (signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGQUIT):signal.signal(sig,signal.SIG_IGN)
 try:
  if attempted:
   c=inspect(container if container and re.fullmatch('[0-9a-f]{64}',container) else NAME)
   if c['Image']!=IMAGE or c['Name']!='/'+NAME or c['Config']['Labels'].get('hr.probe.run')!=RUN:raise RuntimeError('cleanup_ownership_invalid')
   container=c['Id']
   if c['State']['Running']:command(['stop','--time','2',container],timeout=10)
   if inspect(container)['State']['Running']:raise RuntimeError('cleanup_stop_unverified')
   command(['rm',container])
  receipt['owned_client_removed']=True
 except BaseException:receipt.update(status='failed',owned_client_removed=False)
 receipt['finished_at']=time.time()
 if ROOT.exists():(ROOT/'operation.json').write_text(json.dumps(receipt))
 print(json.dumps(receipt))
raise SystemExit(0 if receipt['status']=='passed' else 1)
